export const KIND = {"id":22,"example":{"id":"E22","kind":22,"source":"aether","statement":["Write a function `evens::evens_up_to(int n)` that returns a `std::vector<int>` of the even numbers from 2 to n, smallest first.","Limits: 0 ≤ n ≤ 1000."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <vector>","","namespace evens {","","std::vector<int> evens_up_to(int n)","{","    std::vector<int> result {};","    for (int number {2}; number <= n; number += 2) {","        result.push_back(number);","    }","    return result;","}","","}  // namespace evens"],"frame":[0,2,4,15],"labels":[{"at":2,"level":0,"text":"Include `vector`, the part of the library that holds `std::vector`, a list of values."},{"at":6,"level":1,"text":"Write a function that builds a new list one item at a time and gives it back."},{"at":6,"level":0,"text":"Write `std::vector<int>`, a list of `int` values, as the type of the answer."},{"at":8,"level":2,"text":"Start the result as an empty list."},{"at":8,"level":0,"text":"Make a list that starts empty with `{}`."},{"at":9,"level":2,"text":"Add each even number from 2 to n."},{"at":10,"level":0,"text":"Add a value at the end of the list with `push_back`."},{"at":12,"level":2,"text":"Give back the result."}],"blanks":[]}},"trace":{"id":"T22","lines":["#include <iostream>","#include <print>","#include <vector>","std::vector<int> squares(int n)","{","    std::vector<int> result(n);","    for (int i {0}; i < n; ++i) {","        result[i] = (i + 1) * (i + 1);","    }","    return result;","}","","int main()","{","    int n {0};","    std::cin >> n;","    std::println(\"{}\", squares(n));","}"],"columns":["n","result","i"],"inputs":["3\n","4\n"],"rows":[{"line":15,"values":["0","",""]},{"line":16,"values":["3","",""]},{"line":6,"values":["3","[0, 0, 0]",""]},{"line":7,"values":["3","[0, 0, 0]","0"]},{"line":8,"values":["3","[1, 0, 0]","0"]},{"line":7,"values":["3","[1, 0, 0]","1"]},{"line":8,"values":["3","[1, 4, 0]","1"]},{"line":7,"values":["3","[1, 4, 0]","2"]},{"line":8,"values":["3","[1, 4, 9]","2"]},{"line":7,"values":["3","[1, 4, 9]",""]},{"line":17,"values":["3","",""]}],"output":"[1, 4, 9, 16]\n"},"traces":[],"problems":{"22.01":{"id":"22.01","kind":22,"source":"exercism","statement":["Write a function `secret_handshake::commands(int value)` that returns a `std::vector<std::string>` of actions read from the bits of value.","The bit for 1 adds `wink`, the bit for 2 `double blink`, the bit for 4 `close your eyes` and the bit for 8 `jump`, in that order.","When the bit for 16 is set, the actions come in the reverse order.","A value with none of the bits for 1 to 8 set gives an empty list.","Limits: 0 ≤ value ≤ 31."],"examples":[{"input":"wink_for_1","output":""}],"tests":[{"input":"double_blink_for_10","output":""},{"input":"close_your_eyes_for_100","output":""},{"input":"jump_for_1000","output":""},{"input":"combine_two_actions","output":""},{"input":"reverse_two_actions","output":""},{"input":"reversing_one_action_gives_the_same_action","output":""},{"input":"reversing_no_actions_still_gives_no_actions","output":""},{"input":"all_possible_actions","output":""},{"input":"reverse_all_possible_actions","output":""},{"input":"do_nothing_for_zero","output":""}],"solution":{"lines":["#pragma once","","#include <algorithm>","#include <string>","#include <vector>","","namespace secret_handshake {","","std::vector<std::string> commands(int value)","{","    const std::vector<std::string> actions {","        \"wink\", \"double blink\", \"close your eyes\", \"jump\"};","    std::vector<std::string> result {};","    for (int bit {0}; bit < 4; ++bit) {","        if ((value >> bit) % 2 == 1) {","            result.push_back(actions[bit]);","        }","    }","    if ((value >> 4) % 2 == 1) {","        std::ranges::reverse(result);","    }","    return result;","}","","}  // namespace secret_handshake"],"frame":[0,2,3,4,6,24],"labels":[{"at":8,"level":1,"text":"Write a function that builds a new list one item at a time and gives it back."},{"at":10,"level":2,"text":"Make the list of the 4 actions, the one for the lowest bit first."},{"at":12,"level":2,"text":"Start the result as an empty list."},{"at":13,"level":2,"text":"For each of the 4 bits, lowest first, add its action when the bit is 1."},{"at":18,"level":2,"text":"Reverse the result when the bit for 16 is 1."},{"at":21,"level":2,"text":"Give back the result."}],"blanks":[{"line":8,"from":34,"to":43},{"line":11,"from":8,"to":14},{"line":12,"from":36,"to":38},{"line":14,"from":12,"to":35},{"line":18,"from":8,"to":29},{"line":21,"from":11,"to":17}]},"fn":{"slug":"secret-handshake","commit":"8d139cb0","header":"secret_handshake.h","name":"secret_handshake_test.cpp","test":"#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n#include <string>\n#include <vector>\n\n#include \"secret_handshake.h\"\n\nusing namespace std;\n\n// Secret-handshake exercise test case data version 1.2.1\n\nTEST_CASE(\"wink_for_1\") {\n    REQUIRE(vector<string>{\"wink\"} == secret_handshake::commands(1));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"double_blink_for_10\") {\n    REQUIRE(vector<string>{\"double blink\"} == secret_handshake::commands(2));\n}\n\nTEST_CASE(\"close_your_eyes_for_100\") {\n    REQUIRE(vector<string>{\"close your eyes\"} == secret_handshake::commands(4));\n}\n\nTEST_CASE(\"jump_for_1000\") {\n    REQUIRE(vector<string>{\"jump\"} == secret_handshake::commands(8));\n}\n\nTEST_CASE(\"combine_two_actions\") {\n    REQUIRE(vector<string>{\"wink\", \"double blink\"} ==\n            secret_handshake::commands(3));\n}\n\nTEST_CASE(\"reverse_two_actions\") {\n    REQUIRE(vector<string>{\"double blink\", \"wink\"} ==\n            secret_handshake::commands(19));\n}\n\nTEST_CASE(\"reversing_one_action_gives_the_same_action\") {\n    REQUIRE(vector<string>{\"jump\"} == secret_handshake::commands(24));\n}\n\nTEST_CASE(\"reversing_no_actions_still_gives_no_actions\") {\n    REQUIRE(vector<string>{} == secret_handshake::commands(16));\n}\n\nTEST_CASE(\"all_possible_actions\") {\n    REQUIRE(vector<string>{\"wink\", \"double blink\", \"close your eyes\", \"jump\"} ==\n            secret_handshake::commands(15));\n}\n\nTEST_CASE(\"reverse_all_possible_actions\") {\n    REQUIRE(vector<string>{\"jump\", \"close your eyes\", \"double blink\", \"wink\"} ==\n            secret_handshake::commands(31));\n}\n\nTEST_CASE(\"do_nothing_for_zero\") {\n    REQUIRE(vector<string>{} == secret_handshake::commands(0));\n}\n\n#endif  // !EXERCISM_RUN_ALL_TESTS\n","setup":[],"calls":[{"call":"secret_handshake::commands(1)","expected":"vector<string>{\"wink\"}"}]}},"22.02":{"id":"22.02","kind":22,"source":"exercism","statement":["Write a function `protein_translation::proteins(std::string rna)` that returns the list of amino acids the text codes for.","Read the text 3 letters at a time, from the start; each group of 3 letters is a codon.","The codons and their amino acids:","AUG Methionine; UUU, UUC Phenylalanine; UUA, UUG Leucine; UCU, UCC, UCA, UCG Serine; UAU, UAC Tyrosine; UGU, UGC Cysteine; UGG Tryptophan.","UAA, UAG and UGA are stop codons: return the list at the first one, and ignore everything after it.","Throw an exception (of any type) at a codon not in this list, or at a last group shorter than 3 letters, when no stop codon comes before it.","The empty text gives the empty list.","Limits: 0 ≤ length of the text ≤ 1000."],"examples":[{"input":"Methionine RNA sequence","output":""}],"tests":[{"input":"Phenylalanine RNA sequence 1","output":""},{"input":"Phenylalanine RNA sequence 2","output":""},{"input":"Leucine RNA sequence 1","output":""},{"input":"Leucine RNA sequence 2","output":""},{"input":"Serine RNA sequence 1","output":""},{"input":"Serine RNA sequence 2","output":""},{"input":"Serine RNA sequence 3","output":""},{"input":"Serine RNA sequence 4","output":""},{"input":"Tyrosine RNA sequence 1","output":""},{"input":"Tyrosine RNA sequence 2","output":""},{"input":"Cysteine RNA sequence 1","output":""},{"input":"Cysteine RNA sequence 2","output":""},{"input":"Tryptophan RNA sequence","output":""},{"input":"STOP codon RNA sequence 1","output":""},{"input":"STOP codon RNA sequence 2","output":""},{"input":"STOP codon RNA sequence 3","output":""},{"input":"Translate RNA strand into correct protein list","output":""},{"input":"Sequence of two protein codons translates into proteins","output":""},{"input":"Sequence of two different protein codons translates into proteins","output":""},{"input":"Empty RNA sequence results in no proteins","output":""},{"input":"Translation stops if STOP codon at beginning of sequence","output":""},{"input":"Translation stops if STOP codon at end of two-codon sequence","output":""},{"input":"Translation stops if STOP codon at end of three-codon sequence","output":""},{"input":"Translation stops if STOP codon in middle of three-codon sequence","output":""},{"input":"Translation stops if STOP codon in middle of six-codon sequence","output":""},{"input":"Sequence of two non-STOP codons does not translate to a STOP codon","output":""},{"input":"Non-existing codon can't translate","output":""},{"input":"Unknown amino acids, not part of a codon, can't translate","output":""},{"input":"Incomplete RNA sequence can't translate","output":""},{"input":"Incomplete RNA sequence can translate if valid until a STOP codon","output":""}],"solution":{"lines":["#pragma once","","#include <map>","#include <string>","#include <vector>","","namespace protein_translation {","","std::vector<std::string> proteins(std::string rna)","{","    const std::map<std::string, std::string> amino_acids {","        {\"AUG\", \"Methionine\"},","        {\"UUU\", \"Phenylalanine\"}, {\"UUC\", \"Phenylalanine\"},","        {\"UUA\", \"Leucine\"}, {\"UUG\", \"Leucine\"},","        {\"UCU\", \"Serine\"}, {\"UCC\", \"Serine\"},","        {\"UCA\", \"Serine\"}, {\"UCG\", \"Serine\"},","        {\"UAU\", \"Tyrosine\"}, {\"UAC\", \"Tyrosine\"},","        {\"UGU\", \"Cysteine\"}, {\"UGC\", \"Cysteine\"},","        {\"UGG\", \"Tryptophan\"},","        {\"UAA\", \"STOP\"}, {\"UAG\", \"STOP\"}, {\"UGA\", \"STOP\"}};","    std::vector<std::string> result {};","    for (std::size_t pos {0}; pos < rna.size(); pos += 3) {","        const std::string codon {rna.substr(pos, 3)};","        const std::string amino_acid {amino_acids.at(codon)};","        if (amino_acid == \"STOP\") {","            break;","        }","        result.push_back(amino_acid);","    }","    return result;","}","","}  // namespace protein_translation"],"frame":[0,2,3,4,6,32],"labels":[{"at":8,"level":1,"text":"Write a function that builds a new list one item at a time and gives it back."},{"at":10,"level":2,"text":"Make the map from each codon to its amino acid, or to STOP."},{"at":20,"level":2,"text":"Start the result as an empty list."},{"at":21,"level":2,"text":"For each codon in order, stop at STOP, else add its amino acid, where `at` throws for a codon the map lacks."},{"at":29,"level":2,"text":"Give back the result."}],"blanks":[{"line":8,"from":34,"to":49},{"line":11,"from":16,"to":28},{"line":20,"from":4,"to":28},{"line":24,"from":12,"to":32},{"line":29,"from":11,"to":17}]},"fn":{"slug":"protein-translation","commit":"8d139cb0","header":"protein_translation.h","name":"protein_translation_test.cpp","test":"#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n#include <string>\n#include <vector>\n\n#include \"protein_translation.h\"\n\nusing namespace std;\n\n// Secret-handshake exercise test case data version 1.2.1\n\nTEST_CASE(\"Methionine RNA sequence\", \"[96d3d44f-34a2-4db4-84cd-fff523e069be]\") {\n    REQUIRE(vector<string>{\"Methionine\"} ==\n            protein_translation::proteins(\"AUG\"));\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"Phenylalanine RNA sequence 1\",\n          \"[1b4c56d8-d69f-44eb-be0e-7b17546143d9]\") {\n    REQUIRE(vector<string>{\"Phenylalanine\"} ==\n            protein_translation::proteins(\"UUU\"));\n}\n\nTEST_CASE(\"Phenylalanine RNA sequence 2\",\n          \"[81b53646-bd57-4732-b2cb-6b1880e36d11]\") {\n    REQUIRE(vector<string>{\"Phenylalanine\"} ==\n            protein_translation::proteins(\"UUC\"));\n}\n\nTEST_CASE(\"Leucine RNA sequence 1\", \"[42f69d4f-19d2-4d2c-a8b0-f0ae9ee1b6b4]\") {\n    REQUIRE(vector<string>{\"Leucine\"} == protein_translation::proteins(\"UUA\"));\n}\n\nTEST_CASE(\"Leucine RNA sequence 2\", \"[ac5edadd-08ed-40a3-b2b9-d82bb50424c4]\") {\n    REQUIRE(vector<string>{\"Leucine\"} == protein_translation::proteins(\"UUG\"));\n}\n\nTEST_CASE(\"Serine RNA sequence 1\", \"[8bc36e22-f984-44c3-9f6b-ee5d4e73f120]\") {\n    REQUIRE(vector<string>{\"Serine\"} == protein_translation::proteins(\"UCU\"));\n}\n\nTEST_CASE(\"Serine RNA sequence 2\", \"[5c3fa5da-4268-44e5-9f4b-f016ccf90131]\") {\n    REQUIRE(vector<string>{\"Serine\"} == protein_translation::proteins(\"UCC\"));\n}\n\nTEST_CASE(\"Serine RNA sequence 3\", \"[00579891-b594-42b4-96dc-7ff8bf519606]\") {\n    REQUIRE(vector<string>{\"Serine\"} == protein_translation::proteins(\"UCA\"));\n}\n\nTEST_CASE(\"Serine RNA sequence 4\", \"[08c61c3b-fa34-4950-8c4a-133945570ef6]\") {\n    REQUIRE(vector<string>{\"Serine\"} == protein_translation::proteins(\"UCG\"));\n}\n\nTEST_CASE(\"Tyrosine RNA sequence 1\", \"[54e1e7d8-63c0-456d-91d2-062c72f8eef5]\") {\n    REQUIRE(vector<string>{\"Tyrosine\"} == protein_translation::proteins(\"UAU\"));\n}\n\nTEST_CASE(\"Tyrosine RNA sequence 2\", \"[47bcfba2-9d72-46ad-bbce-22f7666b7eb1]\") {\n    REQUIRE(vector<string>{\"Tyrosine\"} == protein_translation::proteins(\"UAC\"));\n}\n\nTEST_CASE(\"Cysteine RNA sequence 1\", \"[3a691829-fe72-43a7-8c8e-1bd083163f72]\") {\n    REQUIRE(vector<string>{\"Cysteine\"} == protein_translation::proteins(\"UGU\"));\n}\n\nTEST_CASE(\"Cysteine RNA sequence 2\", \"[1b6f8a26-ca2f-43b8-8262-3ee446021767]\") {\n    REQUIRE(vector<string>{\"Cysteine\"} == protein_translation::proteins(\"UGC\"));\n}\n\nTEST_CASE(\"Tryptophan RNA sequence\", \"[1e91c1eb-02c0-48a0-9e35-168ad0cb5f39]\") {\n    REQUIRE(vector<string>{\"Tryptophan\"} ==\n            protein_translation::proteins(\"UGG\"));\n}\n\nTEST_CASE(\"STOP codon RNA sequence 1\",\n          \"[e547af0b-aeab-49c7-9f13-801773a73557]\") {\n    REQUIRE(vector<string>{} == protein_translation::proteins(\"UAA\"));\n}\n\nTEST_CASE(\"STOP codon RNA sequence 2\",\n          \"[67640947-ff02-4f23-a2ef-816f8a2ba72e]\") {\n    REQUIRE(vector<string>{} == protein_translation::proteins(\"UAG\"));\n}\n\nTEST_CASE(\"STOP codon RNA sequence 3\",\n          \"[9c2ad527-ebc9-4ace-808b-2b6447cb54cb]\") {\n    REQUIRE(vector<string>{} == protein_translation::proteins(\"UGA\"));\n}\n\nTEST_CASE(\"Translate RNA strand into correct protein list\",\n          \"[d0f295df-fb70-425c-946c-ec2ec185388e]\") {\n    REQUIRE(vector<string>{\"Methionine\", \"Phenylalanine\", \"Tryptophan\"} ==\n            protein_translation::proteins(\"AUGUUUUGG\"));\n}\n\nTEST_CASE(\"Sequence of two protein codons translates into proteins\",\n          \"[f4d9d8ee-00a8-47bf-a1e3-1641d4428e54]\") {\n    REQUIRE(vector<string>{\"Phenylalanine\", \"Phenylalanine\"} ==\n            protein_translation::proteins(\"UUUUUU\"));\n}\n\nTEST_CASE(\"Sequence of two different protein codons translates into proteins\",\n          \"[dd22eef3-b4f1-4ad6-bb0b-27093c090a9d]\") {\n    REQUIRE(vector<string>{\"Leucine\", \"Leucine\"} ==\n            protein_translation::proteins(\"UUAUUG\"));\n}\n\nTEST_CASE(\"Empty RNA sequence results in no proteins\",\n          \"[2c44f7bf-ba20-43f7-a3bf-f2219c0c3f98]\") {\n    REQUIRE(vector<string>{} == protein_translation::proteins(\"\"));\n}\n\nTEST_CASE(\"Translation stops if STOP codon at beginning of sequence\",\n          \"[e30e8505-97ec-4e5f-a73e-5726a1faa1f4]\") {\n    REQUIRE(vector<string>{} == protein_translation::proteins(\"UAGUGG\"));\n}\n\nTEST_CASE(\"Translation stops if STOP codon at end of two-codon sequence\",\n          \"[5358a20b-6f4c-4893-bce4-f929001710f3]\") {\n    REQUIRE(vector<string>{\"Tryptophan\"} ==\n            protein_translation::proteins(\"UGGUAG\"));\n}\n\nTEST_CASE(\"Translation stops if STOP codon at end of three-codon sequence\",\n          \"[ba16703a-1a55-482f-bb07-b21eef5093a3]\") {\n    REQUIRE(vector<string>{\"Methionine\", \"Phenylalanine\"} ==\n            protein_translation::proteins(\"AUGUUUUAA\"));\n}\n\nTEST_CASE(\"Translation stops if STOP codon in middle of three-codon sequence\",\n          \"[4089bb5a-d5b4-4e71-b79e-b8d1f14a2911]\") {\n    REQUIRE(vector<string>{\"Tryptophan\"} ==\n            protein_translation::proteins(\"UGGUAGUGG\"));\n}\n\nTEST_CASE(\"Translation stops if STOP codon in middle of six-codon sequence\",\n          \"[2c2a2a60-401f-4a80-b977-e0715b23b93d]\") {\n    REQUIRE(vector<string>{\"Tryptophan\", \"Cysteine\", \"Tyrosine\"} ==\n            protein_translation::proteins(\"UGGUGUUAUUAAUGGUUU\"));\n}\n\nTEST_CASE(\"Sequence of two non-STOP codons does not translate to a STOP codon\",\n          \"[f6f92714-769f-4187-9524-e353e8a41a80]\") {\n    REQUIRE(vector<string>{\"Methionine\", \"Methionine\"} ==\n            protein_translation::proteins(\"AUGAUG\"));\n}\n\nTEST_CASE(\"Non-existing codon can't translate\",\n          \"[1e75ea2a-f907-4994-ae5c-118632a1cb0f]\") {\n    REQUIRE_THROWS(protein_translation::proteins(\"AAA\"));\n}\n\nTEST_CASE(\"Unknown amino acids, not part of a codon, can't translate\",\n          \"[9eac93f3-627a-4c90-8653-6d0a0595bc6f]\") {\n    REQUIRE_THROWS(protein_translation::proteins(\"XYZ\"));\n}\n\nTEST_CASE(\"Incomplete RNA sequence can't translate\",\n          \"[9d73899f-e68e-4291-b1e2-7bf87c00f024]\") {\n    REQUIRE_THROWS(protein_translation::proteins(\"AUGU\"));\n}\n\nTEST_CASE(\"Incomplete RNA sequence can translate if valid until a STOP codon\",\n          \"[43945cf7-9968-402d-ab9f-b8a28750b050]\") {\n    REQUIRE(vector<string>{\"Phenylalanine\", \"Phenylalanine\"} ==\n            protein_translation::proteins(\"UUCUUCUAAUGGU\"));\n}\n#endif  // !EXERCISM_RUN_ALL_TESTS\n","setup":[],"calls":[{"call":"protein_translation::proteins(\"AUG\")","expected":"vector<string>{\"Methionine\"}"}]}},"22.03":{"id":"22.03","kind":22,"source":"exercism","statement":["Write a function `diamond::rows(char letter)` that returns, as a `std::vector<std::string>`, the rows of a diamond of letters that runs from `A` down to letter and back to `A`.","Say letter is d places after `A`: there are 2d + 1 rows, each 2d + 1 characters wide.","Row k from the top, and row k from the bottom, with k from 0 to d, hold the letter k places after `A` at positions d - k and d + k, counting from 0, and spaces everywhere else.","Limits: letter is an uppercase letter from `A` to `Z`."],"examples":[{"input":"Degenerate case with a single 'A' row","output":""}],"tests":[{"input":"Degenerate case with no row containing 3 distinct groups of spaces","output":""},{"input":"Smallest non-degenerate case with odd diamond side length","output":""},{"input":"Smallest non-degenerate case with even diamond side length","output":""},{"input":"Largest possible diamond","output":""}],"solution":{"lines":["#pragma once","","#include <cstdlib>","#include <string>","#include <vector>","","namespace diamond {","","std::vector<std::string> rows(char letter)","{","    const int size {2 * (letter - 'A') + 1};","    std::vector<std::string> result {};","    for (int row {0}; row < size; ++row) {","        const int distance {std::abs(size / 2 - row)};","        std::string line(size, ' ');","        line[distance] = static_cast<char>(letter - distance);","        line[size - 1 - distance] = line[distance];","        result.push_back(line);","    }","    return result;","}","","}  // namespace diamond"],"frame":[0,2,3,4,6,22],"labels":[{"at":8,"level":1,"text":"Write a function that builds a new list one item at a time and gives it back."},{"at":10,"level":2,"text":"Work out the size, 2 times the distance of the letter from `A`, plus 1."},{"at":11,"level":2,"text":"Start the result as an empty list."},{"at":12,"level":2,"text":"For each row, add a row of spaces with the row's letter at its 2 places."},{"at":19,"level":2,"text":"Give back the result."}],"blanks":[{"line":8,"from":30,"to":41},{"line":10,"from":20,"to":42},{"line":11,"from":36,"to":38},{"line":15,"from":43,"to":60},{"line":19,"from":11,"to":17}]},"fn":{"slug":"diamond","commit":"8d139cb0","header":"diamond.h","name":"diamond_test.cpp","test":"#include \"diamond.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\n/*\n The tests contained within this canonical data file are suitable\n for value-based testing, in which each test case checks that the\n value returned by the function under test is in every way\n identical to a given expected value.\n\n This exercise is also amenable to property-based testing, in which\n each test case verifies that the value returned by the function\n under test exhibits a specific desired property.\n\n Several tracks (notably, C# and Go) forgo the value-based tests\n below in favor of property-based tests. If you are feeling\n adventurous and would like to use this exercise to introduce the\n concept of property-based testing to participants in your track,\n please ignore the value-based tests below and instead reference\n the test suites in the aforementioned tracks.\n*/\n\nTEST_CASE(\"Degenerate case with a single 'A' row\",\n          \"[202fb4cc-6a38-4883-9193-a29d5cb92076]\") {\n    std::vector<std::string> expected{\"A\"};\n    REQUIRE(diamond::rows('A') == expected);\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"Degenerate case with no row containing 3 distinct groups of spaces\",\n          \"[bd6a6d78-9302-42e9-8f60-ac1461e9abae]\") {\n    std::vector<std::string> expected{\" A \", \"B B\", \" A \"};\n    REQUIRE(diamond::rows('B') == expected);\n}\n\nTEST_CASE(\"Smallest non-degenerate case with odd diamond side length\",\n          \"[af8efb49-14ed-447f-8944-4cc59ce3fd76]\") {\n    std::vector<std::string> expected{\"  A  \", \" B B \", \"C   C\", \" B B \",\n                                      \"  A  \"};\n    REQUIRE(diamond::rows('C') == expected);\n}\n\nTEST_CASE(\"Smallest non-degenerate case with even diamond side length\",\n          \"[e0c19a95-9888-4d05-86a0-fa81b9e70d1d]\") {\n    std::vector<std::string> expected{\"   A   \", \"  B B  \", \" C   C \",\n                                      \"D     D\", \" C   C \", \"  B B  \",\n                                      \"   A   \"};\n    REQUIRE(diamond::rows('D') == expected);\n}\n\nTEST_CASE(\"Largest possible diamond\",\n          \"[82ea9aa9-4c0e-442a-b07e-40204e925944]\") {\n    std::vector<std::string> expected{\n        \"                         A                         \",\n        \"                        B B                        \",\n        \"                       C   C                       \",\n        \"                      D     D                      \",\n        \"                     E       E                     \",\n        \"                    F         F                    \",\n        \"                   G           G                   \",\n        \"                  H             H                  \",\n        \"                 I               I                 \",\n        \"                J                 J                \",\n        \"               K                   K               \",\n        \"              L                     L              \",\n        \"             M                       M             \",\n        \"            N                         N            \",\n        \"           O                           O           \",\n        \"          P                             P          \",\n        \"         Q                               Q         \",\n        \"        R                                 R        \",\n        \"       S                                   S       \",\n        \"      T                                     T      \",\n        \"     U                                       U     \",\n        \"    V                                         V    \",\n        \"   W                                           W   \",\n        \"  X                                             X  \",\n        \" Y                                               Y \",\n        \"Z                                                 Z\",\n        \" Y                                               Y \",\n        \"  X                                             X  \",\n        \"   W                                           W   \",\n        \"    V                                         V    \",\n        \"     U                                       U     \",\n        \"      T                                     T      \",\n        \"       S                                   S       \",\n        \"        R                                 R        \",\n        \"         Q                               Q         \",\n        \"          P                             P          \",\n        \"           O                           O           \",\n        \"            N                         N            \",\n        \"             M                       M             \",\n        \"              L                     L              \",\n        \"               K                   K               \",\n        \"                J                 J                \",\n        \"                 I               I                 \",\n        \"                  H             H                  \",\n        \"                   G           G                   \",\n        \"                    F         F                    \",\n        \"                     E       E                     \",\n        \"                      D     D                      \",\n        \"                       C   C                       \",\n        \"                        B B                        \",\n        \"                         A                         \"};\n    REQUIRE(diamond::rows('Z') == expected);\n}\n#endif\n","setup":["std::vector<std::string> expected{\"A\"};"],"calls":[{"call":"diamond::rows('A')","expected":"expected"}]}},"22.04":{"id":"22.04","kind":22,"source":"exercism","statement":["Write a function `series::slice(const std::string& text, int length)` that returns a `std::vector<std::string>` of every run of `length` side-by-side characters of the text, in the order they start.","It throws `std::domain_error` when the length is below 1 or above the length of the text, so empty text always throws.","Limits: 0 ≤ length of text ≤ 1000, -1000 ≤ length ≤ 1000; text holds digits."],"examples":[{"input":"slices_of_one_from_one","output":""}],"tests":[{"input":"slices_of_one_from_two","output":""},{"input":"slices_of_two","output":""},{"input":"slices_of_two_overlap","output":""},{"input":"slices_can_include_duplicates","output":""},{"input":"slices_of_a_long_series","output":""},{"input":"slice_length_is_too_large","output":""},{"input":"slice_length_cannot_be_zero","output":""},{"input":"slice_length_cannot_be_negative","output":""},{"input":"empty_series_is_invalid","output":""}],"solution":{"lines":["#pragma once","","#include <stdexcept>","#include <string>","#include <vector>","","namespace series {","","std::vector<std::string> slice(const std::string& text,","                               int length)","{","    const int size {static_cast<int>(text.size())};","    if (length < 1 || length > size) {","        throw std::domain_error {\"length out of range\"};","    }","    std::vector<std::string> result {};","    for (int start {0}; start + length <= size; ++start) {","        result.push_back(text.substr(start, length));","    }","    return result;","}","","}  // namespace series"],"frame":[0,2,3,4,6,22],"labels":[{"at":8,"level":1,"text":"Write a function that builds a new list one item at a time and gives it back."},{"at":11,"level":2,"text":"Throw `std::domain_error` for a length below 1 or above the text's."},{"at":15,"level":2,"text":"Start the result as an empty list."},{"at":16,"level":2,"text":"Add the part of that length that starts at each index."},{"at":19,"level":2,"text":"Give back the result."}],"blanks":[{"line":9,"from":31,"to":41},{"line":12,"from":8,"to":35},{"line":15,"from":36,"to":38},{"line":17,"from":25,"to":51},{"line":19,"from":11,"to":17}]},"fn":{"slug":"series","commit":"8d139cb0","header":"series.h","name":"series_test.cpp","test":"#include \"series.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n#include <stdexcept>\nusing namespace std;\n\nTEST_CASE(\"slices_of_one_from_one\") {\n    const vector<string> expected{\"1\"};\n\n    const vector<string> actual{series::slice(\"1\", 1)};\n\n    REQUIRE(expected == actual);\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"slices_of_one_from_two\") {\n    const vector<string> expected{\"1\", \"2\"};\n\n    const vector<string> actual{series::slice(\"12\", 1)};\n\n    REQUIRE(expected == actual);\n}\n\nTEST_CASE(\"slices_of_two\") {\n    const vector<string> expected{\"35\"};\n\n    const vector<string> actual{series::slice(\"35\", 2)};\n\n    REQUIRE(expected == actual);\n}\n\nTEST_CASE(\"slices_of_two_overlap\") {\n    const vector<string> expected{\"91\", \"14\", \"42\"};\n\n    const vector<string> actual{series::slice(\"9142\", 2)};\n\n    REQUIRE(expected == actual);\n}\n\nTEST_CASE(\"slices_can_include_duplicates\") {\n    const vector<string> expected{\"777\", \"777\", \"777\", \"777\"};\n\n    const vector<string> actual{series::slice(\"777777\", 3)};\n\n    REQUIRE(expected == actual);\n}\n\nTEST_CASE(\"slices_of_a_long_series\") {\n    const vector<string> expected{\"91849\", \"18493\", \"84939\", \"49390\",\n                                  \"93904\", \"39042\", \"90424\", \"04243\"};\n\n    const vector<string> actual{series::slice(\"918493904243\", 5)};\n\n    REQUIRE(expected == actual);\n}\n\nTEST_CASE(\"slice_length_is_too_large\") {\n    REQUIRE_THROWS_AS(series::slice(\"12345\", 6), domain_error);\n}\n\nTEST_CASE(\"slice_length_cannot_be_zero\") {\n    REQUIRE_THROWS_AS(series::slice(\"12345\", 0), domain_error);\n}\n\nTEST_CASE(\"slice_length_cannot_be_negative\") {\n    REQUIRE_THROWS_AS(series::slice(\"123\", -1), domain_error);\n}\n\nTEST_CASE(\"empty_series_is_invalid\") {\n    REQUIRE_THROWS_AS(series::slice(\"\", 1), domain_error);\n}\n#endif\n","setup":["const vector<string> expected{\"1\"};","const vector<string> actual{series::slice(\"1\", 1)};"],"calls":[{"call":"actual","expected":"expected"}]}}}}
